import{_ as e,o as l,c as a,a3 as s}from"./chunks/framework.bvEHUNtb.js";const f=JSON.parse('{"title":"C-04 十二建除","description":"从月建、节气与十二值日神，理解传统历书中建、除、满、平等日期标注的逻辑。","frontmatter":{"title":"C-04 十二建除","description":"从月建、节气与十二值日神，理解传统历书中建、除、满、平等日期标注的逻辑。","category":"guide","outline":"deep","aliases":["十二建除","建除十二神","十二值日"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/twelve-day-officers.md","filePath":"topics/traditional-wisdom/common-knowledge/twelve-day-officers.md","lastUpdated":1786982540000}'),n={name:"topics/traditional-wisdom/common-knowledge/twelve-day-officers.md"};function d(i,t,r,p,o,g){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="c-04-·-十二建除-历书中的日期结构" tabindex="-1">C-04 · 十二建除：历书中的日期结构 <a class="header-anchor" href="#c-04-·-十二建除-历书中的日期结构" aria-label="Permalink to &quot;C-04 · 十二建除：历书中的日期结构&quot;">​</a></h1><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 文化通识篇（C系列）· 时间历法组<br><strong>版本：</strong> v1.0（2026年8月）<br><strong>前置篇目（必读）：</strong> 12·十二地支 / 14·二十四节气 / C-02·北斗七星与斗建<br><strong>后续篇目：</strong> C-05·三伏三九 / C-06·岁时节令体系</p><hr><h2 id="写在前面-为什么要学十二建除" tabindex="-1">写在前面：为什么要学十二建除？ <a class="header-anchor" href="#写在前面-为什么要学十二建除" aria-label="Permalink to &quot;写在前面：为什么要学十二建除？&quot;">​</a></h2><p>翻开中国传统历书（老黄历），每一天的日期旁边，<br> 都有一个字：<strong>建、除、满、平、定、执、破、危、成、收、开、闭</strong>。</p><p>这十二个字，周而复始，循环不断。<br> 它们不是装饰，而是一套完整的<strong>日期能量评估系统</strong>——<br> 古人用它来判断每一天适合做什么、不适合做什么。</p><p>不懂十二建除：</p><ul><li>看不懂传统历书（老黄历）的基本标注</li><li>读不懂《协纪辨方书》《通书》等择日典籍</li><li>无法理解古代&quot;择吉&quot;文化的底层逻辑</li><li>读古代文书、契约、日记时，遇到建除标注一头雾水</li></ul><p><strong>本篇目标：</strong><br> 还原十二建除的天文来源、推算方法、各神含义与吉凶宜忌，<br> 厘清建除与月建、节气的关系，<br> 以及建除在择日文化中的实际应用逻辑。</p><hr><h2 id="一、俯瞰-十二建除在体系中的位置" tabindex="-1">一、俯瞰：十二建除在体系中的位置 <a class="header-anchor" href="#一、俯瞰-十二建除在体系中的位置" aria-label="Permalink to &quot;一、俯瞰：十二建除在体系中的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北斗斗柄指向（C-02·斗建）</span></span>
<span class="line"><span>  └─ 月建（每月地支）</span></span>
<span class="line"><span>       └─ 十二建除 ← 本篇核心</span></span>
<span class="line"><span>            ├─ 从月建起&quot;建&quot;，顺行十二辰</span></span>
<span class="line"><span>            ├─ 每日对应一个建除神</span></span>
<span class="line"><span>            └─ 以建除神判断当日宜忌</span></span>
<span class="line"><span>                 ├─ 接续 C-05·三伏三九（特殊时间节点）</span></span>
<span class="line"><span>                 ├─ 接续 C-06·岁时节令体系（节令宜忌）</span></span>
<span class="line"><span>                 └─ 延伸 Shu·择日体系（直接调用）</span></span></code></pre></div><p><strong>一句话定位：</strong><br> 十二建除，是以月建为起点、顺行十二地支，为每一天赋予一个&quot;能量标签&quot;的择日基础工具。<br> 它是古代历书中出现频率最高的日期标注之一。</p><h2 id="二、十二建除的天文根源" tabindex="-1">二、十二建除的天文根源 <a class="header-anchor" href="#二、十二建除的天文根源" aria-label="Permalink to &quot;二、十二建除的天文根源&quot;">​</a></h2><h3 id="_2-1-建除从哪里来" tabindex="-1">2.1 建除从哪里来？ <a class="header-anchor" href="#_2-1-建除从哪里来" aria-label="Permalink to &quot;2.1 建除从哪里来？&quot;">​</a></h3><p>十二建除，直接来源于<strong>北斗斗柄的指向</strong>（月建）。</p><p>【原典】《协纪辨方书》卷四<br> 【原文】历书日历家以建除满平定执破危成收开闭，凡十二日，周而复始，观所值以定吉凶。每月交节，则叠两值日。其法从月建上起建，与斗杓所指相应。如正月建寅，则寅日起建，顺行十二辰是也。<br> 【版本】清·允禄等奉敕撰，《钦定四库全书》本</p><p>这段话是十二建除推算方法的<strong>最权威官方定义</strong>：</p><ul><li>从月建（当月地支）起&quot;建&quot;</li><li>顺行十二辰（地支顺序）</li><li>每日对应一个建除神</li><li>每月交节时，会出现&quot;叠两值日&quot;（同一天有两个建除神）</li></ul><h3 id="_2-2-与北斗斗建的关系" tabindex="-1">2.2 与北斗斗建的关系 <a class="header-anchor" href="#_2-2-与北斗斗建的关系" aria-label="Permalink to &quot;2.2 与北斗斗建的关系&quot;">​</a></h3><p>【原典】《淮南子·天文训》<br> 【原文】&quot;正月指寅，十二月指丑，一岁而匝，终而复始。&quot;<br> 【版本】西汉·刘安撰，高诱注本（中国哲学书电子化计划）</p><p>月建，是北斗斗柄所指方位的直接对应。<br> 十二建除以月建为起点，本质上是将北斗的天文运行，落地为每日可操作的时间能量坐标。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北斗斗柄指寅（正月）</span></span>
<span class="line"><span>  → 月建为寅</span></span>
<span class="line"><span>  → 寅日起&quot;建&quot;</span></span>
<span class="line"><span>  → 卯日为&quot;除&quot;</span></span>
<span class="line"><span>  → 辰日为&quot;满&quot;</span></span>
<span class="line"><span>  → ……以此类推</span></span></code></pre></div><h3 id="_2-3-历史沿革" tabindex="-1">2.3 历史沿革 <a class="header-anchor" href="#_2-3-历史沿革" aria-label="Permalink to &quot;2.3 历史沿革&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">时代</th><th style="text-align:left;">发展阶段</th><th style="text-align:left;">代表文献</th></tr></thead><tbody><tr><td style="text-align:left;">先秦</td><td style="text-align:left;">建除概念萌芽，与月建同步出现</td><td style="text-align:left;">《淮南子·天文训》（汉初整理先秦资料）</td></tr><tr><td style="text-align:left;">西汉</td><td style="text-align:left;">建除体系基本成型，进入历书</td><td style="text-align:left;">《史记·历书》《汉书·律历志》</td></tr><tr><td style="text-align:left;">魏晋南北朝</td><td style="text-align:left;">敦煌历书中大量出现建除标注</td><td style="text-align:left;">敦煌写本历书（等）</td></tr><tr><td style="text-align:left;">唐宋</td><td style="text-align:left;">建除成为官方历书标准项目</td><td style="text-align:left;">《新唐书·历志》《宋史·律历志》</td></tr><tr><td style="text-align:left;">清代</td><td style="text-align:left;">系统化整理，吉凶宜忌完全定型</td><td style="text-align:left;">《协纪辨方书》（钦定）</td></tr></tbody></table><h2 id="三、推算方法-如何确定每日建除" tabindex="-1">三、推算方法：如何确定每日建除？ <a class="header-anchor" href="#三、推算方法-如何确定每日建除" aria-label="Permalink to &quot;三、推算方法：如何确定每日建除？&quot;">​</a></h2><h3 id="_3-1-基本规则" tabindex="-1">3.1 基本规则 <a class="header-anchor" href="#_3-1-基本规则" aria-label="Permalink to &quot;3.1 基本规则&quot;">​</a></h3><p><strong>第一步：确定月建</strong><br> 当月节气入节后，月建即定。<br> （注意：以&quot;节&quot;为界，不以农历初一为界）</p><table tabindex="0"><thead><tr><th style="text-align:left;">月建</th><th style="text-align:left;">节气起点</th><th style="text-align:left;">地支</th></tr></thead><tbody><tr><td style="text-align:left;">建寅</td><td style="text-align:left;">立春</td><td style="text-align:left;">寅</td></tr><tr><td style="text-align:left;">建卯</td><td style="text-align:left;">惊蛰</td><td style="text-align:left;">卯</td></tr><tr><td style="text-align:left;">建辰</td><td style="text-align:left;">清明</td><td style="text-align:left;">辰</td></tr><tr><td style="text-align:left;">建巳</td><td style="text-align:left;">立夏</td><td style="text-align:left;">巳</td></tr><tr><td style="text-align:left;">建午</td><td style="text-align:left;">芒种</td><td style="text-align:left;">午</td></tr><tr><td style="text-align:left;">建未</td><td style="text-align:left;">小暑</td><td style="text-align:left;">未</td></tr><tr><td style="text-align:left;">建申</td><td style="text-align:left;">立秋</td><td style="text-align:left;">申</td></tr><tr><td style="text-align:left;">建酉</td><td style="text-align:left;">白露</td><td style="text-align:left;">酉</td></tr><tr><td style="text-align:left;">建戌</td><td style="text-align:left;">寒露</td><td style="text-align:left;">戌</td></tr><tr><td style="text-align:left;">建亥</td><td style="text-align:left;">立冬</td><td style="text-align:left;">亥</td></tr><tr><td style="text-align:left;">建子</td><td style="text-align:left;">大雪</td><td style="text-align:left;">子</td></tr><tr><td style="text-align:left;">建丑</td><td style="text-align:left;">小寒</td><td style="text-align:left;">丑</td></tr></tbody></table><p><strong>第二步：从月建地支起&quot;建&quot;，顺行十二辰</strong></p><p>以正月（建寅）为例：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>寅日 → 建</span></span>
<span class="line"><span>卯日 → 除</span></span>
<span class="line"><span>辰日 → 满</span></span>
<span class="line"><span>巳日 → 平</span></span>
<span class="line"><span>午日 → 定</span></span>
<span class="line"><span>未日 → 执</span></span>
<span class="line"><span>申日 → 破</span></span>
<span class="line"><span>酉日 → 危</span></span>
<span class="line"><span>戌日 → 成</span></span>
<span class="line"><span>亥日 → 收</span></span>
<span class="line"><span>子日 → 开</span></span>
<span class="line"><span>丑日 → 闭</span></span>
<span class="line"><span>（下一个寅日 → 再起建，循环）</span></span></code></pre></div><h3 id="_3-2-交节叠日" tabindex="-1">3.2 交节叠日 <a class="header-anchor" href="#_3-2-交节叠日" aria-label="Permalink to &quot;3.2 交节叠日&quot;">​</a></h3><p>每月交节时（如从正月建寅进入二月建卯），会出现<strong>同一天有两个建除神</strong>的情况，称为&quot;叠两值日&quot;。</p><p>【原典】《协纪辨方书》卷四<br> 【原文】每月交节，则叠两值日。<br> 【版本】清·允禄等奉敕撰，《钦定四库全书》本</p><p>这是建除推算中最需要注意的细节——交节当天，前一个月的建除神与新月的建除神同时存在，择日时需特别处理。</p><h2 id="四、十二建除神-·-各神详解" tabindex="-1">四、十二建除神 · 各神详解 <a class="header-anchor" href="#四、十二建除神-·-各神详解" aria-label="Permalink to &quot;四、十二建除神 · 各神详解&quot;">​</a></h2><p>【原典】《协纪辨方书》卷三<br> 【原文】建，青龙也……除，明堂也……满，天刑也……平，朱雀也……定，金匮也……执，天德也……破，白虎也……危，玉堂也……成，天牢也……收，玄武也……开，司命也……闭，勾陈也。<br> 【版本】清·允禄等奉敕撰，《钦定四库全书》本</p><p>十二建除神各有对应的黄道/黑道属性与宜忌。<br> 传统将十二神分为<strong>黄道六神</strong>（吉）与<strong>黑道六神</strong>（凶）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">建除神</th><th style="text-align:left;">黄/黑道</th><th style="text-align:left;">对应神</th><th style="text-align:left;">基本吉凶</th><th style="text-align:left;">核心宜忌</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>建</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">青龙</td><td style="text-align:left;">次吉</td><td style="text-align:left;">宜出行·求官；忌动土·起造</td></tr><tr><td style="text-align:left;"><strong>除</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">明堂</td><td style="text-align:left;">吉</td><td style="text-align:left;">宜祭祀·求医·除旧布新；忌嫁娶</td></tr><tr><td style="text-align:left;"><strong>满</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">天刑</td><td style="text-align:left;">凶</td><td style="text-align:left;">宜仓库·纳财；忌百事</td></tr><tr><td style="text-align:left;"><strong>平</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">朱雀</td><td style="text-align:left;">平</td><td style="text-align:left;">宜平常事；忌出行·诉讼</td></tr><tr><td style="text-align:left;"><strong>定</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">金匮</td><td style="text-align:left;">吉</td><td style="text-align:left;">宜嫁娶·开市·立契；忌出行</td></tr><tr><td style="text-align:left;"><strong>执</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">天德</td><td style="text-align:left;">吉</td><td style="text-align:left;">宜捕猎·纳财；忌开市·嫁娶</td></tr><tr><td style="text-align:left;"><strong>破</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">白虎</td><td style="text-align:left;">大凶</td><td style="text-align:left;">诸事不宜；忌一切重要事项</td></tr><tr><td style="text-align:left;"><strong>危</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">玉堂</td><td style="text-align:left;">吉</td><td style="text-align:left;">宜祭祀·求财；忌登高·出行</td></tr><tr><td style="text-align:left;"><strong>成</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">天牢</td><td style="text-align:left;">次凶</td><td style="text-align:left;">宜嫁娶·开市；忌诉讼</td></tr><tr><td style="text-align:left;"><strong>收</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">玄武</td><td style="text-align:left;">凶</td><td style="text-align:left;">宜收敛·纳财；忌开市·出行</td></tr><tr><td style="text-align:left;"><strong>开</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">司命</td><td style="text-align:left;">大吉</td><td style="text-align:left;">宜百事；诸事皆宜</td></tr><tr><td style="text-align:left;"><strong>闭</strong></td><td style="text-align:left;">黑道</td><td style="text-align:left;">勾陈</td><td style="text-align:left;">凶</td><td style="text-align:left;">宜封闭·安葬；忌开市·嫁娶</td></tr></tbody></table><p>⚠️ <strong>重要说明：</strong><br> 以上吉凶为<strong>基础定义</strong>，实际择日中，建除神需与当日其他神煞（岁神·月神·日神）综合判断，不可单独以建除神论断吉凶。<br> 《协纪辨方书》明确指出：&quot;与吉神遇从所宜，与凶神遇则从其所忌。&quot;</p><h3 id="_4-1-各神字义溯源" tabindex="-1">4.1 各神字义溯源 <a class="header-anchor" href="#_4-1-各神字义溯源" aria-label="Permalink to &quot;4.1 各神字义溯源&quot;">​</a></h3><p>十二建除的字义，本身即含有深刻的哲学内涵：</p><p>【原典】《淮南子·天文训》（节选相关段落）<br> 【版本】西汉·刘安撰，高诱注本</p><table tabindex="0"><thead><tr><th style="text-align:left;">建除神</th><th style="text-align:left;">字义本解</th><th style="text-align:left;">哲学内涵</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>建</strong></td><td style="text-align:left;">建立、确立</td><td style="text-align:left;">万物之始，气机初立</td></tr><tr><td style="text-align:left;"><strong>除</strong></td><td style="text-align:left;">清除、除旧</td><td style="text-align:left;">扫除旧物，为新作准备</td></tr><tr><td style="text-align:left;"><strong>满</strong></td><td style="text-align:left;">盈满、充盈</td><td style="text-align:left;">气机充盈，但满则溢</td></tr><tr><td style="text-align:left;"><strong>平</strong></td><td style="text-align:left;">平稳、均衡</td><td style="text-align:left;">不偏不倚，平和之象</td></tr><tr><td style="text-align:left;"><strong>定</strong></td><td style="text-align:left;">安定、确定</td><td style="text-align:left;">稳固成形，可作决断</td></tr><tr><td style="text-align:left;"><strong>执</strong></td><td style="text-align:left;">执持、把握</td><td style="text-align:left;">执守其位，专注一事</td></tr><tr><td style="text-align:left;"><strong>破</strong></td><td style="text-align:left;">破坏、破裂</td><td style="text-align:left;">气机冲破，诸事不稳</td></tr><tr><td style="text-align:left;"><strong>危</strong></td><td style="text-align:left;">危险、高危</td><td style="text-align:left;">物极将变，需谨慎</td></tr><tr><td style="text-align:left;"><strong>成</strong></td><td style="text-align:left;">成就、完成</td><td style="text-align:left;">事成之象，收获之时</td></tr><tr><td style="text-align:left;"><strong>收</strong></td><td style="text-align:left;">收敛、收藏</td><td style="text-align:left;">收纳归仓，内敛之象</td></tr><tr><td style="text-align:left;"><strong>开</strong></td><td style="text-align:left;">开启、开放</td><td style="text-align:left;">气机大开，百事皆宜</td></tr><tr><td style="text-align:left;"><strong>闭</strong></td><td style="text-align:left;">封闭、关闭</td><td style="text-align:left;">闭藏之象，宜静不宜动</td></tr></tbody></table><p>这十二个字，对应一个完整的<strong>能量周期</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建（立）→ 除（清）→ 满（盈）→ 平（衡）→ 定（稳）→ 执（守）</span></span>
<span class="line"><span>  → 破（变）→ 危（险）→ 成（就）→ 收（藏）→ 开（启）→ 闭（合）</span></span>
<span class="line"><span>  → 再起建……</span></span></code></pre></div><p>这是一个从&quot;建立&quot;到&quot;闭合&quot;的完整生命周期，<br> 与十二长生（长生·沐浴……墓·绝·胎·养）有异曲同工之妙。</p><h2 id="五、黄道吉日-建除与黄道的关系" tabindex="-1">五、黄道吉日：建除与黄道的关系 <a class="header-anchor" href="#五、黄道吉日-建除与黄道的关系" aria-label="Permalink to &quot;五、黄道吉日：建除与黄道的关系&quot;">​</a></h2><h3 id="_5-1-黄道吉日-的来源" tabindex="-1">5.1 &quot;黄道吉日&quot;的来源 <a class="header-anchor" href="#_5-1-黄道吉日-的来源" aria-label="Permalink to &quot;5.1 &quot;黄道吉日&quot;的来源&quot;">​</a></h3><p>日常用语&quot;黄道吉日&quot;，正是来源于十二建除中的<strong>黄道六神</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>黄道六神（吉）：除·平·定·执·危·开（+ 成，部分说法）</span></span>
<span class="line"><span>黑道六神（凶）：建·满·破·收·闭（+ 成，部分说法）</span></span></code></pre></div><p>【原典】《协纪辨方书》卷三<br> 【原文】&quot;黄道者，日之所行也。建除十二神，黄道六神值日，诸事皆宜；黑道六神值日，诸事宜慎。&quot;<br> 【版本】清·允禄等奉敕撰，《钦定四库全书》本</p><p>⚠️ <strong>&quot;黄道吉日&quot;的误用说明：</strong><br> 现代口语中&quot;黄道吉日&quot;常泛指&quot;好日子&quot;，但在传统择日体系中，黄道吉日有严格的技术定义——特指建除十二神中黄道六神值日之日，并非所有&quot;好日子&quot;都可以称为黄道吉日。</p><h3 id="_5-2-建除与黄道十二宫的区别" tabindex="-1">5.2 建除与黄道十二宫的区别 <a class="header-anchor" href="#_5-2-建除与黄道十二宫的区别" aria-label="Permalink to &quot;5.2 建除与黄道十二宫的区别&quot;">​</a></h3><p>⚠️ <strong>极易混淆的概念：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">来源</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>建除十二神的黄道</strong></td><td style="text-align:left;">中国传统择日体系</td><td style="text-align:left;">十二建除神中属&quot;吉&quot;的六神，与天文黄道无直接关系</td></tr><tr><td style="text-align:left;"><strong>黄道十二宫</strong></td><td style="text-align:left;">西方占星体系（经由印度传入）</td><td style="text-align:left;">太阳在黄道带上运行经过的十二个星座区间</td></tr></tbody></table><p>两者名称相近，但<strong>完全是两套不同的体系</strong>，读古籍时务必根据语境区分。</p><h2 id="六、实际应用-建除在择日中如何使用" tabindex="-1">六、实际应用：建除在择日中如何使用？ <a class="header-anchor" href="#六、实际应用-建除在择日中如何使用" aria-label="Permalink to &quot;六、实际应用：建除在择日中如何使用？&quot;">​</a></h2><h3 id="_6-1-传统历书中的建除" tabindex="-1">6.1 传统历书中的建除 <a class="header-anchor" href="#_6-1-传统历书中的建除" aria-label="Permalink to &quot;6.1 传统历书中的建除&quot;">​</a></h3><p>翻开任何一本传统历书（通书·老黄历），<br> 每日标注格式大致如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>某年某月某日（干支）</span></span>
<span class="line"><span>建除神：开（黄道·司命）</span></span>
<span class="line"><span>宜：嫁娶·开市·动土·出行……</span></span>
<span class="line"><span>忌：……</span></span></code></pre></div><p>建除神是历书中<strong>最基础的日期标注</strong>，是普通百姓择日的第一参考。</p><h3 id="_6-2-建除与其他神煞的配合" tabindex="-1">6.2 建除与其他神煞的配合 <a class="header-anchor" href="#_6-2-建除与其他神煞的配合" aria-label="Permalink to &quot;6.2 建除与其他神煞的配合&quot;">​</a></h3><p>建除神在实际择日中，需与以下神煞配合使用：</p><table tabindex="0"><thead><tr><th style="text-align:left;">神煞层级</th><th style="text-align:left;">代表神煞</th><th style="text-align:left;">与建除的关系</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>年神</strong></td><td style="text-align:left;">太岁·岁破·三煞</td><td style="text-align:left;">年度大方向，优先级最高</td></tr><tr><td style="text-align:left;"><strong>月神</strong></td><td style="text-align:left;">月建·月破·月德</td><td style="text-align:left;">月度方向，次于年神</td></tr><tr><td style="text-align:left;"><strong>日神</strong></td><td style="text-align:left;">建除十二神</td><td style="text-align:left;">日度判断，最常用</td></tr><tr><td style="text-align:left;"><strong>时神</strong></td><td style="text-align:left;">时干支·贵人</td><td style="text-align:left;">时辰判断，最精细</td></tr></tbody></table><p>【原典】《协纪辨方书》卷一<br> 【原文】&quot;用事之法，先观年神，次观月神，次观日神，次观时神，层层相参，方为完备。&quot;<br> 【版本】清·允禄等奉敕撰，《钦定四库全书》本</p><p>建除神属于&quot;日神&quot;层级，是四个层级中<strong>最常用、最直观</strong>的一层，但不可脱离年神、月神单独使用。</p><h3 id="_6-3-实例演示" tabindex="-1">6.3 实例演示 <a class="header-anchor" href="#_6-3-实例演示" aria-label="Permalink to &quot;6.3 实例演示&quot;">​</a></h3><p>以<strong>2026年8月7日（立秋）</strong> 为例：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>立秋入节 → 月建从建未转为建申</span></span>
<span class="line"><span>建申月，申日 → 起&quot;建&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>立秋当日：建（黑道·青龙）</span></span>
<span class="line"><span>次日（酉日）：除（黄道·明堂）</span></span>
<span class="line"><span>……</span></span>
<span class="line"><span></span></span>
<span class="line"><span>注意：立秋当日为交节叠日，</span></span>
<span class="line"><span>同时存在建未月的&quot;闭&quot;与建申月的&quot;建&quot;，</span></span>
<span class="line"><span>择日时需特别处理。</span></span></code></pre></div><h2 id="七、道家与哲学视角-建除的深层含义" tabindex="-1">七、道家与哲学视角：建除的深层含义 <a class="header-anchor" href="#七、道家与哲学视角-建除的深层含义" aria-label="Permalink to &quot;七、道家与哲学视角：建除的深层含义&quot;">​</a></h2><p>十二建除，不仅是择日工具，<br> 更是先人对<strong>时间能量周期</strong>的深刻观察。</p><p>【原典】《淮南子·天文训》<br> 【原文】&quot;天道曰圆，地道曰方……阴阳相薄，感而生风……月徙一辰，复返其所，正月指寅，十二月指丑，一岁而匝，终而复始。&quot;<br> 【版本】西汉·刘安撰，高诱注本（中国哲学书电子化计划）</p><p>建除的哲学本质：</p><p>时间不是均质的 —— 每一天的&quot;能量状态&quot;不同，如同潮水有涨有落，如同人有精力旺盛与疲惫之时。</p><p>先人的智慧，在于：不强行逆势而为，而是顺应时间的自然节律，在合适的时间做合适的事。</p><p>这不是迷信，而是一种&quot;顺势而为&quot;的时间哲学。这与道家&quot;无为而治&quot;的核心思想高度一致——不是什么都不做，而是<strong>顺应自然节律而为</strong>。</p><h2 id="八、现代视角-如何看待建除文化" tabindex="-1">八、现代视角：如何看待建除文化？ <a class="header-anchor" href="#八、现代视角-如何看待建除文化" aria-label="Permalink to &quot;八、现代视角：如何看待建除文化？&quot;">​</a></h2><p><strong>建除的合理内核：</strong></p><ol><li><strong>时间节律观：</strong> 建除体系承认时间是有节律的，不同时间段有不同的能量状态。这与现代生物节律学（chronobiology）的研究方向有相通之处——人体确实存在日节律、月节律、年节律。</li><li><strong>决策框架：</strong> 建除为古人提供了一套<strong>标准化的决策参考框架</strong>。在信息不充分的情况下，有一套系统性的参考，好过完全随机决策。</li><li><strong>心理锚定：</strong> 选择&quot;黄道吉日&quot;办大事，本质上是一种<strong>心理准备仪式</strong>——在特定日期做重要决定，会更认真、更慎重，这本身就有积极意义。</li></ol><p><strong>需要理性看待的部分：</strong><br> 建除体系是古代农业社会的产物，其吉凶宜忌的具体内容（如&quot;宜嫁娶&quot;&quot;忌动土&quot;），是特定历史文化背景下的经验总结，不宜机械照搬，应以文化理解的态度对待。</p><h2 id="九、跨体系接口" tabindex="-1">九、跨体系接口 <a class="header-anchor" href="#九、跨体系接口" aria-label="Permalink to &quot;九、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">建除的作用</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>C-02·北斗斗建</strong></td><td style="text-align:left;">直接来源</td><td style="text-align:left;">月建来自斗柄指向，建除以月建为起点</td></tr><tr><td style="text-align:left;"><strong>C-01·太岁</strong></td><td style="text-align:left;">配合使用</td><td style="text-align:left;">太岁年神与建除日神，是择日的两个核心层级</td></tr><tr><td style="text-align:left;"><strong>主干14·二十四节气</strong></td><td style="text-align:left;">交节叠日</td><td style="text-align:left;">每逢节气交接，建除出现叠日，需特别处理</td></tr><tr><td style="text-align:left;"><strong>主干12·十二地支</strong></td><td style="text-align:left;">推算基础</td><td style="text-align:left;">建除顺行十二地支，地支是推算的基本单位</td></tr><tr><td style="text-align:left;"><strong>Shu·择日体系</strong></td><td style="text-align:left;">核心工具</td><td style="text-align:left;">建除是传统择日（通书·老黄历）的基础标注</td></tr><tr><td style="text-align:left;"><strong>Shu·奇门遁甲</strong></td><td style="text-align:left;">参考配合</td><td style="text-align:left;">奇门择时与建除日神可配合参考</td></tr></tbody></table><h2 id="十、与主干-c系列的连接" tabindex="-1">十、与主干/C系列的连接 <a class="header-anchor" href="#十、与主干-c系列的连接" aria-label="Permalink to &quot;十、与主干/C系列的连接&quot;">​</a></h2><p><strong>接续（前置）：</strong></p><ul><li>← 主干12·十二地支（建除顺行十二地支，地支为推算基础）</li><li>← 主干14·二十四节气（月建以节为界，交节产生叠日）</li><li>← C-01·太岁（年神与日神的层级关系）</li><li>← C-02·北斗七星与斗建（月建来源，建除的天文根源）</li></ul><p><strong>延伸（后续）：</strong></p><ul><li>→ C-05·三伏三九（特殊时间节点与建除的配合）</li><li>→ C-06·岁时节令体系（节令择日与建除的综合应用）</li><li>→ Shu·择日体系（建除作为核心工具直接调用）</li></ul><h2 id="十一、本章小结" tabindex="-1">十一、本章小结 <a class="header-anchor" href="#十一、本章小结" aria-label="Permalink to &quot;十一、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>十二建除 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 天文来源：</span></span>
<span class="line"><span>   建除以月建为起点，月建来自北斗斗柄指向</span></span>
<span class="line"><span>   从月建地支起&quot;建&quot;，顺行十二辰，每日一神</span></span>
<span class="line"><span>   《协纪辨方书》：&quot;其法从月建上起建，与斗杓所指相应&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 十二神结构：</span></span>
<span class="line"><span>   建除满平定执破危成收开闭，周而复始</span></span>
<span class="line"><span>   黄道六神（除·平·定·执·危·开）为吉</span></span>
<span class="line"><span>   黑道六神（建·满·破·收·闭·成）为凶</span></span>
<span class="line"><span>   &quot;黄道吉日&quot;即源于此</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 使用原则：</span></span>
<span class="line"><span>   建除为&quot;日神&quot;层级，需配合年神（太岁）、月神综合判断</span></span>
<span class="line"><span>   交节当日出现叠日，需特别处理</span></span>
<span class="line"><span>   《协纪辨方书》：&quot;与吉神遇从所宜，与凶神遇则从其所忌&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 哲学内涵：</span></span>
<span class="line"><span>   十二建除是先人对时间能量周期的系统观察</span></span>
<span class="line"><span>   从&quot;建立&quot;到&quot;闭合&quot;，构成完整的能量循环</span></span>
<span class="line"><span>   体现道家&quot;顺势而为&quot;的时间哲学</span></span></code></pre></div><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《协纪辨方书》卷三、卷四，清·允禄等奉敕撰，《钦定四库全书》本</td><td style="text-align:left;">建除推算方法定义；十二神黄黑道属性；各神宜忌；叠日处理；用事层级</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《淮南子·天文训》，西汉·刘安撰，高诱注本（中国哲学书电子化计划）</td><td style="text-align:left;">月建斗建原文；天道圆方·阴阳节律；建除哲学背景</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">敦煌写本历书（P.2765等），唐代，敦煌研究院藏</td><td style="text-align:left;">建除在唐代官方历书中的实际标注形式；最早的历书实物证据</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">《史记·历书》，西汉·司马迁撰（中国哲学书电子化计划）</td><td style="text-align:left;">建除体系进入汉代历书的历史背景；月建与历法的关系</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">《新唐书·历志》，宋·欧阳修等撰，二十四史标准本</td><td style="text-align:left;">建除作为官方历书标准项目的唐代文献依据</td></tr></tbody></table><hr><p><strong>前置篇：</strong> C-03·三垣体系<br><strong>后续篇：</strong> C-05·三伏三九</p>`,95)])])}const y=e(n,[["render",d]]);export{f as __pageData,y as default};
